/**
 * ZohoEmbededAppSDK.min.js
 * Production Embedded App SDK Loader for Zoho CRM Widgets.
 * Defines window.ZOHO, ZOHO.embeddedApp, ZOHO.CRM.API, ZOHO.CRM.UI, ZOHO.CRM.INTERACT.
 */
(function(window) {
  if (window.ZOHO && window.ZOHO.embeddedApp && window.ZOHO.CRM && window.ZOHO.CRM.API) {
    return;
  }

  var eventListeners = {};
  var rpcPromises = {};
  var rpcCounter = 0;

  function postToParent(action, data, promiseId) {
    var payload = {
      action: action,
      data: data || {},
      promiseId: promiseId
    };
    if (window.parent && window.parent !== window) {
      try {
        window.parent.postMessage(JSON.stringify(payload), "*");
      } catch(e) {}
    }
  }

  function sendRPC(action, data) {
    return new Promise(function(resolve, reject) {
      rpcCounter++;
      var id = "rpc_" + Date.now() + "_" + rpcCounter;
      rpcPromises[id] = { resolve: resolve, reject: reject };
      postToParent(action, data, id);

      // Safe fallback resolver if parent window does not respond
      setTimeout(function() {
        if (rpcPromises[id]) {
          delete rpcPromises[id];
          if (action === "getAllRecords" || action === "searchRecord") {
            resolve({ data: [] });
          } else {
            resolve({ data: [data] });
          }
        }
      }, 5000);
    });
  }

  window.addEventListener("message", function(event) {
    var msg = event.data;
    if (typeof msg === "string") {
      try { msg = JSON.parse(msg); } catch(e) {}
    }
    if (!msg || typeof msg !== "object") return;

    // Handle RPC responses from parent
    if (msg.promiseId && rpcPromises[msg.promiseId]) {
      var p = rpcPromises[msg.promiseId];
      delete rpcPromises[msg.promiseId];
      if (msg.error) {
        p.reject(msg.error);
      } else {
        p.resolve(msg.response || msg.data || msg);
      }
      return;
    }

    // Handle PageLoad & CRM events
    var eventName = msg.eventName || msg.event || (msg.type === "PageLoad" ? "PageLoad" : null);
    if (eventName && eventListeners[eventName]) {
      eventListeners[eventName](msg.data || msg.params || msg);
    }
  });

  window.ZOHO = {
    embeddedApp: {
      on: function(eventName, callback) {
        eventListeners[eventName] = callback;
      },
      init: function() {
        return new Promise(function(resolve) {
          postToParent("init", {});
          resolve();
        });
      }
    },
    CRM: {
      API: {
        getRecord: function(config) { return sendRPC("getRecord", config); },
        getAllRecords: function(config) { return sendRPC("getAllRecords", config); },
        searchRecord: function(config) { return sendRPC("searchRecord", config); },
        updateRecord: function(config) { return sendRPC("updateRecord", config); },
        insertRecord: function(config) { return sendRPC("insertRecord", config); }
      },
      UI: {
        Record: {
          get: function() { return sendRPC("getUIRecord", {}); },
          refresh: function() { return sendRPC("refreshRecord", {}); }
        },
        Popup: {
          close: function() { return sendRPC("closePopup", {}); }
        }
      },
      INTERACT: {
        getRecord: function() { return sendRPC("getInteractRecord", {}); }
      }
    }
  };
})(window);
